edits.before:
  const instance = Dropdown.getOrCreateInstance(getToggleButton)

  if (isEscapeEvent) {
    instance.hide()
    return
  }

  if (isUpOrDownEvent) {
    instance.show()
    instance._selectMenuItem(event)
  }
}

edits.after:
  const instance = Dropdown.getOrCreateInstance(getToggleButton)

  if (isEscapeEvent) {
    instance.hide()
    instance._element.focus()
    return
  }

  if (isUpOrDownEvent) {
    instance.show()
    instance._selectMenuItem(event)
  }
}
